import raw from "./data/results.json";

/** Generated by backend/scripts/build_results_json.py from the Detect-Trust-Adapt results.txt. Do not edit by hand. */

export type Stat = { mean: number; std: number } | null;

export type Policy =
  | "never"
  | "always_tent"
  | "gated_tent"
  | "gated_bn"
  | "oracle_tent"
  | "ours"
  | "oracle_ses";

export type AblationPolicy =
  | Policy
  | "old_gate_ses"
  | "new_gate_tent"
  | "new_gate_bn_ema"
  | "new_gate_blend"
  | "ses_always_on"
  | "oracle_bn_only"
  | "oracle_grad_only";

type CoreRow = {
  experiment: string;
  policy: Policy;
  overall: Stat;
  clean: Stat;
  shift: Stat;
  post_clean: Stat;
  worst_window: Stat;
  macro_f1: Stat;
  adapt_steps?: Stat;
  clean_adapted?: Stat;
  false_alarms?: Stat;
  fa_per_1k?: Stat;
  delay?: Stat;
  missed?: Stat;
  shift_coverage?: Stat;
  resets?: Stat;
};
type ShuffledRow = {
  experiment: string;
  policy: Policy;
  overall: Stat;
  clean: Stat;
  shift: Stat;
  adapt_steps?: Stat;
  false_alarms?: Stat;
  delay?: Stat;
  missed?: Stat;
  shift_coverage?: Stat;
};
type PairedRow = {
  order: "correlated" | "shuffled";
  experiment: string;
  policy: Policy;
  mean_diff: number;
  min: number;
  max: number;
  better: number;
  equal: number;
  worse: number;
  shift_diff: number | null;
};
type DetectorRow = { order: "correlated" | "shuffled"; detector: string; clean: Stat; tunnel: Stat; fog: Stat };
type AblationRow = { experiment: string; policy: AblationPolicy; overall: Stat; clean: Stat; shift: Stat };
type StaticRow = {
  data: string;
  condition: "clean" | "tunnel" | "fog";
  severity: number;
  resnet18: number;
  hog_svm: number;
};

const data = raw as unknown as {
  stream_seeds: number[];
  config: { detector: string; m: number; k: number; N0: number; adapter: string };
  core: CoreRow[];
  paired: PairedRow[];
  shuffled: ShuffledRow[];
  detectors: DetectorRow[];
  nominal_entropy_ks_clean: { correlated: Stat; shuffled: Stat };
  ablations: AblationRow[];
  static: StaticRow[];
};

export const CONFIG = data.config;
export const N_SEEDS = data.stream_seeds.length;
export const NOMINAL_KS_CLEAN = data.nominal_entropy_ks_clean;

export const EXPERIMENTS = [
  { id: "E1_clean", label: "E1 · Clean" },
  { id: "E2_tunnel_bursts", label: "E2 · Tunnel" },
  { id: "E3_fog_bursts", label: "E3 · Fog" },
  { id: "E4_recovery", label: "E4 · Tunnel → fog" },
  { id: "E5_slow_fog", label: "E5 · Slow fog" },
] as const;

export const POLICY_LABEL: Record<AblationPolicy, string> = {
  never: "Never adapt",
  always_tent: "Always TENT",
  gated_tent: "Gated TENT (original)",
  gated_bn: "Gated BN (original)",
  oracle_tent: "Oracle TENT (perfect timing)",
  ours: "Detect–Trust–Adapt (ours)",
  oracle_ses: "Ours, perfect timing",
  old_gate_ses: "Old entropy gate + new adapter",
  new_gate_tent: "New gate + TENT",
  new_gate_bn_ema: "New gate + BN-EMA",
  new_gate_blend: "New gate + fixed-prior blend",
  ses_always_on: "New adapter always on, no gate / reset",
  oracle_bn_only: "Batch statistics only (no gradient)",
  oracle_grad_only: "Entropy gradient only (source statistics)",
};

export const DETECTOR_LABEL: Record<string, string> = {
  entropy: "Entropy-KS (original)",
  bbsds: "BBSDs",
  "stat:pixel": "Raw pixel statistics",
  "stat:stem": "BN statistics, stem only",
  "stat:shallow": "BN statistics, shallow layers",
  "stat:all": "Content-normalised BN statistics (ours)",
};

function must<T>(row: T | undefined, what: string): T {
  if (!row) throw new Error(`Missing result: ${what}`);
  return row;
}

export const core = (exp: string, policy: Policy) =>
  must(data.core.find((r) => r.experiment === exp && r.policy === policy), `core ${exp}/${policy}`);

export const hasCore = (exp: string, policy: Policy) =>
  data.core.some((r) => r.experiment === exp && r.policy === policy);

export const shuffled = (exp: string, policy: Policy) =>
  must(data.shuffled.find((r) => r.experiment === exp && r.policy === policy), `shuffled ${exp}/${policy}`);

export const paired = (exp: string, policy: Policy, order: "correlated" | "shuffled" = "correlated") =>
  must(
    data.paired.find((r) => r.experiment === exp && r.policy === policy && r.order === order),
    `paired ${order}/${exp}/${policy}`,
  );

export const detector = (name: string, order: "correlated" | "shuffled" = "correlated") =>
  must(data.detectors.find((r) => r.detector === name && r.order === order), `detector ${order}/${name}`);

export const detectorNames = (order: "correlated" | "shuffled" = "correlated") =>
  data.detectors.filter((r) => r.order === order).map((r) => r.detector);

export const ablation = (exp: string, policy: AblationPolicy) =>
  must(data.ablations.find((r) => r.experiment === exp && r.policy === policy), `ablation ${exp}/${policy}`);

/** Frame-level ResNet-18 accuracy (%) on held-out test tracks. */
export const staticAcc = (condition: "clean" | "tunnel" | "fog", severity: number) =>
  must(
    data.static.find(
      (r) => r.data === "held-out test tracks" && r.condition === condition && r.severity === severity,
    ),
    `static ${condition}/${severity}`,
  ).resnet18;

export const fmt = (s: Stat | undefined, digits = 1) => (s ? s.mean.toFixed(digits) : "–");
export const fmtPm = (s: Stat | undefined, digits = 1) =>
  s ? `${s.mean.toFixed(digits)} ± ${s.std.toFixed(digits)}` : "–";
export const val = (s: Stat | undefined) => (s ? Number(s.mean.toFixed(1)) : 0);
export const signed = (v: number, digits = 1) => `${v > 0 ? "+" : v < 0 ? "−" : "±"}${Math.abs(v).toFixed(digits)}`;
